package android.media;public class AudioFormat {public static final int ENCODING_PCM_16BIT=2,ENCODING_PCM_FLOAT=4,CHANNEL_OUT_STEREO=12;private int rate,enc,channels;public int getSampleRate(){return rate;}public int getEncoding(){return enc;}public int getChannelCount(){return channels==12?2:1;}public static class Builder {final AudioFormat f=new AudioFormat();public Builder setEncoding(int n){f.enc=n;return this;}public Builder setSampleRate(int n){f.rate=n;return this;}public Builder setChannelMask(int n){f.channels=n;return this;}public AudioFormat build(){return f;}}}